-- Migration: Add tables for MCP access tokens and usage statistics
--
-- mcp_tokens stores API tokens generated by the administrator with descriptions/comments.
-- mcp_stats stores per-tool execution telemetry for usage analytics across tools, callers, and libraries.

-- @migration-step create mcp_tokens table
CREATE TABLE IF NOT EXISTS mcp_tokens (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  token TEXT NOT NULL UNIQUE,
  comment TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  last_used_at DATETIME
);

CREATE INDEX IF NOT EXISTS idx_mcp_tokens_token ON mcp_tokens(token);

-- @migration-step create mcp_stats table
CREATE TABLE IF NOT EXISTS mcp_stats (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  token_id INTEGER REFERENCES mcp_tokens(id) ON DELETE SET NULL,
  token_comment TEXT,
  tool TEXT NOT NULL,
  library TEXT,
  query TEXT,
  detail TEXT,
  success INTEGER NOT NULL DEFAULT 1,
  duration_ms INTEGER DEFAULT 0,
  error_message TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_mcp_stats_created_at ON mcp_stats(created_at);
CREATE INDEX IF NOT EXISTS idx_mcp_stats_tool ON mcp_stats(tool);
CREATE INDEX IF NOT EXISTS idx_mcp_stats_token_id ON mcp_stats(token_id);
CREATE INDEX IF NOT EXISTS idx_mcp_stats_library ON mcp_stats(library);
